// Aggregate only rows with reporting evidence; configuration-only records have no delivery metrics.
function configuredSummary(rows,key){
 const spec=company.metricFormats?.[key]?.aggregate;if(!spec)return null;
 let numerator=0,denominator=0,seen=false;
 for(const row of rows){
  if(row.recordOrigin==='configuration'&&filterNumber(row.Impressions)===null&&(filterNumber(row['Amount spent (INR)'])??0)===0)continue;
  const weightKey=spec.type==='weightedAverage'?spec.weight:spec.denominator;
  let weight=filterNumber(row[weightKey]);
  if(weight===null&&filterNumber(row.Impressions)===0)weight=0;
  if(weight===null||weight<0)return null;
  seen=true;if(weight===0&&spec.type==='weightedAverage')continue;
  let value=filterNumber(row[spec.type==='weightedAverage'?key:spec.numerator]);
  if(value===null&&weight===0)value=0;
  if(value===null)return null;
  numerator+=spec.type==='weightedAverage'?value*weight:value;denominator+=weight;
 }
 const value=seen&&denominator>0?numerator/denominator*(spec.type==='ratioOfSums'?(spec.multiplier??1):1):null;
 return Number.isFinite(value)?value:null;
}

function total(rows,k){if(company.metricFormats?.[k]?.aggregate){const value=configuredSummary(rows,k);return value===null?'—':configuredMetric(value,k);}const present=key=>rows.some(r=>r[key]!==undefined&&r[key]!==null&&r[key]!==''&&r[key]!=='-');if(!['delivery','actions','Ad set budget','Frequency'].includes(k)&&!present(k))return '—';const sum=key=>rows.reduce((n,r)=>n+(Number(r[key])||0),0);if(k==='Amount spent (INR)')return money(sum(k))+'<span class="sub">Total Spent</span>';if(['Impressions','Link clicks','Leads','Website leads','Meta leads','Purchases','Website purchases','Website landing page views','Meeting Booked'].includes(k))return num(sum(k));if(k==='CPM (cost per 1,000 impressions) (INR)')return (sum('Impressions')?money(sum('Amount spent (INR)')/sum('Impressions')*1000):'—')+'<span class="sub">Per 1,000 Impressions</span>';if(k==='CPC (cost per link click) (INR)')return (sum('Link clicks')?money(sum('Amount spent (INR)')/sum('Link clicks')):'—')+'<span class="sub">Per Action</span>';if(k==='Frequency'){const value=summaryFrequency(rows);return value===null?'—':value.toFixed(2)+'<span class="sub">Per Meta account</span>'; }if(k==='CTR (link click-through rate)')return sum('Impressions')?(sum('Link clicks')/sum('Impressions')*100).toFixed(2)+'%':'—';return ['delivery','actions','Ad set budget'].includes(k)?'':'—'}
