function saveEditor(){const drawerEl=$('#drawer'),ids=JSON.parse(drawerEl.dataset.editIds||'[]'),level=drawerEl.dataset.editLevel||state.level,baseline=JSON.parse(drawerEl.dataset.editBaseline||'{}');const fields=$$('#drawer input[id],#drawer select[id],#drawer textarea[id]').filter(el=>el.type!=='file');const changed=Object.fromEntries(fields.filter(el=>editorFieldValue(el)!==baseline[el.id]).map(el=>[el.id,editorFieldValue(el)]));if(Object.hasOwn(changed,'edit-name')&&!changed['edit-name'].trim())return toast('Enter a name.');const invalid=fields.find(el=>Object.hasOwn(changed,el.id)&&!el.checkValidity());if(invalid)return invalid.reportValidity();const min=$('#edit-min-age')?.value,max=$('#edit-max-age')?.value;if(min&&max&&+min>+max)return toast('Minimum age cannot exceed maximum age.');const start=$('#edit-start')?.value,end=$('#edit-end')?.value;if(Object.keys(changed).some(key=>['edit-start','edit-end','edit-start-time','edit-end-time'].includes(key))&&ids.some(id=>!validSchedulePatch(data[level].find(r=>r.id===id),changed)))return toast('End date and time must not be before the start for any selected item.');if(['Daily','Lifetime'].includes(changed['edit-budget-type'])&&filterNumber($('#edit-budget')?.value)===null)return toast('Enter a budget amount for the selected budget type.');const file=$('#edit-image')?.files?.[0];if(file&&file.size>1024*1024)return toast('Please choose an image smaller than 1 MB.');const apply=image=>{let count=0;for(const id of ids){const r=data[level]?.find(r=>r.id===id);if(r&&applyEditorPatch(r,changed,image)){change(r,'Edited local settings',level);count++;}}drawerEl.hidden=true;toast(count?'All edits saved as local drafts.':'No settings changed.');};if(file){const fr=new FileReader();fr.onload=()=>apply(fr.result);fr.readAsDataURL(file)}else apply();}
