function showAdPreview(r){drawer('Ad preview',`<div class="preview-ad"><div class="ad-copy"><b>${esc(r.page||'Facebook Page')}</b><br><small class="muted">Sponsored · Local preview</small></div><div class="ad-copy">${esc(r.copy||'Primary text was not included in the report.')}</div>${r.image?`<img src="${esc(r.image)}" alt="Ad creative">`:'<div class="ad-placeholder">Creative not included in export</div>'}<div class="ad-copy"><small class="muted">${esc(r.url||'Website')}</small><h3>${esc(r.headline||r.name)}</h3>${btn(esc(r.cta||'Learn more'),'preview-cta')}</div></div>`,btn('Edit ad','edit','edit'))}
