function relatedMetricRows(row,level,target){if(level===target)return [row];const order=['campaigns','adsets','ads'];if(order.indexOf(target)<order.indexOf(level)){const direct=row[singular[target]+' ID'];if(direct)return data[target].filter(r=>rowMetaID(r,target)===direct);const parentLevel=level==='ads'?'adsets':'campaigns';const parent=data[parentLevel].find(r=>r.id===row.parentId);return parent?relatedMetricRows(parent,parentLevel,target):[];}const childLevel=level==='campaigns'?'adsets':'ads';return data[childLevel].filter(c=>!c.deleted&&(c.parentId===row.id||(rowMetaID(row,level)&&c[singular[level]+' ID']===rowMetaID(row,level)))).flatMap(c=>relatedMetricRows(c,childLevel,target));}
function matchesMetricFilter(row,level,f){return relatedMetricRows(row,level,f.level).some(r=>{const n=filterNumber(r[f.key]);if(n===null)return false;const value=Number(f.value),upper=Number(f.upper);return f.operator==='gt'?n>value:f.operator==='lt'?n<value:f.operator==='between'?n>=value&&n<=upper:f.operator==='outside'?n<value||n>upper:false;});}

