function duplicateLocalRecord(row,level,name,keep=true){const copy=keep?structuredClone({...row.exportedSettings,...row}):{objective:row.objective||row.exportedSettings?.objective||'',parentId:row.parentId};if(!keep)for(const key of ['Campaign ID','Campaign name','Ad set ID','Ad set name'])if(row[key]!==undefined)copy[key]=row[key];
 const ownID=singular[level]+' ID';for(const key of ['id','metaId','adId',ownID,singular[level]+' delivery','recordOrigin','localRecordId','identitySource','configurationStatus','configurationCampaignStatus','configurationAdsetStatus','configurationObservedDate','settingsSource','exportedSettings'])delete copy[key];
 const numeric=typeof exportNumericKeys==='undefined'?[]:[...exportNumericKeys];const metrics=new Set([...numeric.filter(k=>k!=='Ad set budget'),...columns.map(c=>c[0]).filter(k=>/ranking$|CTR|Rate|CPC|CPM/.test(k)),...Object.keys(company.metricFormats||{})]);for(const key of metrics)if(Object.hasOwn(copy,key))copy[key]='';
 Object.assign(copy,{id:level+'-'+crypto.randomUUID(),name,[singular[level]+' name']:name,delivery:'In draft',on:false,source:'local','Amount spent (INR)':'0',Impressions:'0',Results:''});return copy;}

function duplicateChildren(row,level){const next=level==='campaigns'?'adsets':level==='adsets'?'ads':null;return next?data[next].filter(child=>!child.deleted&&child.parentId===row.id):[];}
function linkedDuplicateCounts(rows,level){const counts={campaigns:0,adsets:0,ads:0};function count(row,current){counts[current]++;const next=current==='campaigns'?'adsets':'ads';for(const child of duplicateChildren(row,current))count(child,next);}rows.forEach(r=>count(r,level));return counts;}
function relinkDuplicate(copy,parent,parentLevel){copy.parentId=parent.id;delete copy[singular[parentLevel]+' ID'];copy[singular[parentLevel]+' name']=parent.name;if(parent.metaId)copy[singular[parentLevel]+' ID']=parent.metaId;if(parentLevel==='adsets'){delete copy['Campaign ID'];delete copy['Campaign name'];if(parent['Campaign ID'])copy['Campaign ID']=parent['Campaign ID'];if(parent['Campaign name'])copy['Campaign name']=parent['Campaign name'];}}
function planLocalDuplicates(originals,level,count,suffix,keep,includeChildren){if(!Number.isInteger(count)||count<1||count>50)throw Error('Choose between 1 and 50 copies.');const plan={records:{campaigns:[],adsets:[],ads:[]},rootIds:[]};function cloneBranch(original,current,name,parent,parentLevel){const copy=duplicateLocalRecord(original,current,name,keep);if(parent)relinkDuplicate(copy,parent,parentLevel);plan.records[current].push(copy);if(includeChildren){const next=current==='campaigns'?'adsets':'ads';for(const child of duplicateChildren(original,current))cloneBranch(child,next,child.name,copy,current);}return copy;}for(const original of originals)for(let i=0;i<count;i++)plan.rootIds.push(cloneBranch(original,level,original.name+suffix+(count>1?' '+(i+1):''),null,null).id);return plan;}

function applyLocalDuplicatePlan(plan){const time=new Date().toISOString();for(const level of Object.keys(labels)){data[level].unshift(...plan.records[level]);for(const r of plan.records[level]){pending.push({id:r.id,level,name:r.name,description:'Duplicated as local draft',time});history.unshift({id:r.id,level,name:r.name,description:'Duplicated as local draft',time});}}state.selection=new Set(plan.rootIds);persist();render();toast(`Created ${plan.records.campaigns.length} campaigns, ${plan.records.adsets.length} ad sets and ${plan.records.ads.length} ads as local drafts.`);}
