// Objective filtering uses reported settings or exact-ID campaign ancestry.
function objectiveFilterValues(){return [...new Set(['App promotion','Awareness','Brand Awareness','Catalogue Sales','Conversions','Desktop App Engagement','Desktop App Installs','Engagement','Event Responses','In-app engagement','Lead Generation','Leads','Messages','Sales','Traffic',...Object.values(data).flat().map(r=>r.objective||r.exportedSettings?.objective||r['Campaign Objective']).filter(Boolean)])].sort((a,b)=>a.localeCompare(b));}
function validObjectiveFilters(value){return Array.isArray(value)?value.filter(f=>f&&['is','not'].includes(f.operator)&&Array.isArray(f.values)&&f.values.length&&f.values.every(v=>typeof v==='string'&&v.trim())):[];}
function recordObjective(row,level){
 const own=row.objective??row.exportedSettings?.objective??row['Campaign Objective'];if(typeof own==='string'&&own.trim())return own.trim();
 if(level==='campaigns')return '';
 const campaign=data.campaigns.find(r=>(row['Campaign ID']&&r.metaId===row['Campaign ID'])||(level==='adsets'&&row.parentId===r.id));
 if(campaign)return recordObjective(campaign,'campaigns');
 if(level==='ads'){const parent=data.adsets.find(r=>(row.parentId&&r.id===row.parentId)||(row['Ad set ID']&&r.metaId===row['Ad set ID']));if(parent)return recordObjective(parent,'adsets');}
 return '';
}
function matchesObjectiveFilter(row,level,f){const value=recordObjective(row,level);if(!value)return false;const matched=f.values.includes(value);return f.operator==='not'?!matched:matched;}
function objectiveFilterChips(){return (state.objectiveFilters||[]).map((f,i)=>`<span class="chip"><button class="filter-chip-edit" data-action="objective-filter-edit:${i}" aria-label="Edit objective filter ${i+1}">Objective ${f.operator==='not'?'not':'is'} ${esc(f.values.join(', '))}</button>${btn('×','objective-filter-remove:'+i,'','',`aria-label="Remove objective filter ${i+1}"`)}</span>`).join('');}
function showObjectiveFilter(){activeFilterEdit=null;filterPopover('Objectives',`<label class="field">Select an operator<select id="objective-filter-operator"><option value="is">is</option><option value="not">not</option></select></label><details class="objective-values"><summary>Select values...</summary><div role="group" aria-label="Objective values">${objectiveFilterValues().map(value=>`<label><input type="checkbox" name="objective-filter-value" value="${esc(value)}">${esc(value)}</label>`).join('')}</div></details>`,btn('Apply','objective-filter-apply','','primary'));}
function applyObjectiveFilter(){const f={operator:$('#objective-filter-operator').value,values:$$('input[name="objective-filter-value"]:checked').map(input=>input.value)};if(!validObjectiveFilters([f]).length)return toast('Select at least one objective.');if(!commitFilterValue('objectiveFilters',f))return;state.page=0;state.selection.clear();persist();$('#popover').hidden=true;render();}

function validRowFilters(value){return Array.isArray(value)?value.filter(f=>f&&Object.hasOwn(singular,f.level)&&Array.isArray(f.ids)&&f.ids.length&&f.ids.every(id=>typeof id==='string'&&id.length>0)).map(f=>({level:f.level,ids:[...new Set(f.ids)]})):[];}
function matchesRowFilter(row,level,filter){return relatedMetricRows(row,level,filter.level).some(r=>!r.deleted&&filter.ids.includes(r.id));}
function rowFilterChips(){return (state.rowFilters||[]).map((f,i)=>`<span class="chip">Filtering ${f.ids.length} ${esc((f.ids.length===1?singular[f.level]:labels[f.level]).toLowerCase())}${btn('×','row-filter-remove:'+i,'','',`aria-label="Remove selected rows filter ${i+1}"`)}</span>`).join('');}
function filterSelectedRows(){const ids=selectedRows().map(r=>r.id);if(!ids.length)return;state.rowFilters=(state.rowFilters||[]).filter(f=>f.level!==state.level);state.rowFilters.push({level:state.level,ids});state.page=0;persist();render();}

function deliveryFilterValues(){return ['Drafts','Pending','Active','Inactive','Not delivering','Deleted','Completed','Off'];}
function validDeliveryFilters(value){return Array.isArray(value)?value.filter(f=>f&&Object.hasOwn(singular,f.level)&&['is','not'].includes(f.operator)&&Array.isArray(f.values)&&f.values.length&&f.values.every(v=>deliveryFilterValues().includes(v))):[];}
function deliveryFilterValue(row){if(row.deleted)return 'Deleted';return ({'In draft':'Drafts','Campaign off':'Not delivering','Ad set off':'Not delivering'})[row.delivery]||row.delivery||'';}
function matchesDeliveryFilter(row,level,f){const values=relatedMetricRows(row,level,f.level).map(deliveryFilterValue).filter(v=>deliveryFilterValues().includes(v));if(!values.length)return false;return f.operator==='not'?values.every(v=>!f.values.includes(v)):values.some(v=>f.values.includes(v));}
function deliveryFilterChips(){return (state.deliveryFilters||[]).map((f,i)=>`<span class="chip"><button class="filter-chip-edit" data-action="delivery-filter-edit:${i}" aria-label="Edit delivery filter ${i+1}">${esc(singular[f.level])} delivery ${f.operator} ${esc(f.values.join(', '))}</button>${btn('×','delivery-filter-remove:'+i,'','',`aria-label="Remove delivery filter ${i+1}"`)}</span>`).join('');}
function showDeliveryFilter(){activeFilterEdit=null;filterPopover('Delivery',`<label class="field">Select the level of the ad object<select id="delivery-filter-level">${Object.entries(singular).map(([level,label])=>`<option value="${level}" ${level===state.level?'selected':''}>${label} delivery</option>`).join('')}</select></label><label class="field">Select an operator<select id="delivery-filter-operator"><option value="is">is</option><option value="not">not</option></select></label><details class="objective-values"><summary>Select values...</summary><div role="group" aria-label="Delivery values">${deliveryFilterValues().map(value=>`<label><input type="checkbox" name="delivery-filter-value" value="${esc(value)}">${esc(value)}</label>`).join('')}</div></details>`,btn('Apply','delivery-filter-apply','','primary'));}
function applyDeliveryFilter(){const f={level:$('#delivery-filter-level').value,operator:$('#delivery-filter-operator').value,values:$$('input[name="delivery-filter-value"]:checked').map(input=>input.value)};if(!validDeliveryFilters([f]).length)return toast('Select at least one delivery status.');if(!commitFilterValue('deliveryFilters',f))return;state.page=0;state.selection.clear();persist();$('#popover').hidden=true;render();}

function summaryFrequency(rows){
 if(rows.length===1)return filterNumber(rows[0].Frequency);
 const value=filterNumber(company.accountFrequency);if(value===null||state.start!==company.reportStart||state.end!==company.reportEnd)return null;
 const original=reference[state.level];if(rows.length!==original.length)return null;
 const byId=new Map(original.map(r=>[r.id,r]));if(new Set(rows.map(r=>r.id)).size!==rows.length)return null;
 const same=rows.every(r=>{const source=byId.get(r.id);return source&&r.source!=='local'&&['Frequency','Reach','Impressions'].every(k=>String(r[k]??'')===String(source[k]??'')||(source.recordOrigin==='configuration'&&filterNumber(source[k])===null&&(filterNumber(r[k])===null||filterNumber(r[k])===0)))&&['Reporting starts','Reporting ends'].every(k=>String(r[k]||company[k==='Reporting starts'?'reportStart':'reportEnd'])===String(source[k]||company[k==='Reporting starts'?'reportStart':'reportEnd']));});
 return same?value:null;
}

function mergeObservedCells(row,source){for(const key of source.screenObservedColumns||[]){if(['Ad set budget','Ad set budget type','Amount spent (INR)'].includes(key)&&!Object.hasOwn(row,key))row[key]=source[key];}if(source.screenMetricsSource&&!row.screenMetricsSource)row.screenMetricsSource=structuredClone(source.screenMetricsSource);}

function validPinnedRows(value){if(!value||typeof value!=='object'||Array.isArray(value))return {campaigns:reference.campaigns.filter(r=>(company.pinnedCampaignIds||[]).includes(r.metaId)).map(r=>r.id),adsets:[],ads:[]};return Object.fromEntries(Object.keys(singular).map(level=>[level,Array.isArray(value[level])?[...new Set(value[level].filter(id=>typeof id==='string'&&data[level].some(r=>r.id===id)))]:[]]));}
function isRowPinned(row,level){return (state.pinnedRows?.[level]||[]).includes(row.id);}
function toggleSelectedPin(){const rows=selectedRows();if(rows.length!==1)return;const row=rows[0],pins=state.pinnedRows[state.level];if(isRowPinned(row,state.level))state.pinnedRows[state.level]=pins.filter(id=>id!==row.id);else pins.push(row.id);persist();render();}

function orderPinnedRows(rows){const pins=state.pinnedRows?.[state.level]||[];if(!pins.length)return rows;const rank=id=>{const index=pins.indexOf(id);return index<0?pins.length:index;};return rows.sort((a,b)=>rank(a.id)-rank(b.id));}

function editExistingFilter(type,index){
 const filter=state[type]?.[index];if(!Number.isInteger(index)||!filter)return;
 if(type==='idFilters')showIDFilter(filter);
 else if(type==='nameFilters')showNameFilter(filter);
 else if(type==='metricFilters'){showMetricFilter(filter.key);$('#metric-filter-level').value=filter.level;$('#metric-filter-operator').value=filter.operator;$('#metric-filter-value').value=filter.value;$('#metric-filter-upper').value=filter.upper??'';$('#metric-filter-upper-field').hidden=!['between','outside'].includes(filter.operator);}
 else if(type==='goalFilters'){showGoalFilter();$('#goal-filter-operator').value=filter.operator;$$('input[name="goal-filter-value"]').forEach(input=>input.checked=filter.values.includes(input.value));}
 else if(type==='objectiveFilters'||type==='deliveryFilters'){
  const kind=type==='objectiveFilters'?'objective':'delivery';if(kind==='objective')showObjectiveFilter();else{showDeliveryFilter();$('#delivery-filter-level').value=filter.level;}
  $('#'+kind+'-filter-operator').value=filter.operator;
  $$('input[name="'+kind+'-filter-value"]').forEach(input=>input.checked=filter.values.includes(input.value));
 }else return;
 activeFilterEdit={type,index,original:JSON.stringify(filter)};
}
function commitFilterValue(type,value){
 if(activeFilterEdit?.type===type){const {index,original}=activeFilterEdit;if(JSON.stringify(state[type][index])!==original){toast('This filter changed while it was open. Reopen it to edit.');return false;}state[type][index]=structuredClone(value);}
 else state[type].push(structuredClone(value));
 activeFilterEdit=null;return true;
}

// Labels observed in the source Performance goal filter. Export enum mapping is explicit.
function goalFilterValues(){return ['Ad recall lift','App installs','Calls','Conversations','Conversions','Qualified leads','Conversion value','Reach','Event response','Impressions','Instagram profile visits','Landing page views','Leads','Link Clicks','Page Likes','Post Engagement','Reminders set','ThruPlay','2-second continuous video plays','6-second video plays'];}
function validGoalFilters(value){return Array.isArray(value)?value.filter(f=>f&&['is','not'].includes(f.operator)&&Array.isArray(f.values)&&f.values.length&&f.values.every(v=>goalFilterValues().includes(v))):[];}
function recordPerformanceGoal(row){const raw=row.performanceGoal??row.exportedSettings?.performanceGoal??row['Optimization Goal'];const mapping={OFFSITE_CONVERSIONS:'Conversions',LEAD_GENERATION:'Leads',REACH:'Reach',AD_RECALL_LIFT:'Ad recall lift',LINK_CLICKS:'Link Clicks',CONVERSATIONS:'Conversations'};return (Object.hasOwn(mapping,raw)?mapping[raw]:'')||(goalFilterValues().includes(raw)?raw:'');}
function effectivePerformanceGoal(row,level){
 if(level!=='ads'||row.performanceGoalOverride)return recordPerformanceGoal(row);
 const parent=relatedMetricRows(row,level,'adsets')[0];
 if(parent?.performanceGoalOverride)return recordPerformanceGoal(parent);
 if(Object.hasOwn(row,'performanceGoal'))return recordPerformanceGoal(row);
 return recordPerformanceGoal(row)||(parent?recordPerformanceGoal(parent):'');
}
function matchesGoalFilter(row,level,f){
 const values=level==='campaigns'?relatedMetricRows(row,level,'adsets').map(recordPerformanceGoal):[effectivePerformanceGoal(row,level)];
 if(!values.length)return false;return f.operator==='not'?values.every(value=>value&&!f.values.includes(value)):values.some(value=>value&&f.values.includes(value));
}
function goalFilterChips(){return (state.goalFilters||[]).map((f,i)=>`<span class="chip"><button class="filter-chip-edit" data-action="goal-filter-edit:${i}" aria-label="Edit goal filter ${i+1}">Performance goal ${f.operator==='not'?'not':'is'} ${esc(f.values.join(', '))}</button>${btn('×','goal-filter-remove:'+i,'','',`aria-label="Remove goal filter ${i+1}"`)}</span>`).join('');}
function showGoalFilter(){activeFilterEdit=null;filterPopover('Performance goal',`<label class="field">Select an operator<select id="goal-filter-operator"><option value="is">is</option><option value="not">not</option></select></label><details class="objective-values goal-values"><summary>Select values...</summary><div role="group" aria-label="Performance goal values">${goalFilterValues().map(value=>`<label><input type="checkbox" name="goal-filter-value" value="${esc(value)}">${esc(value)}</label>`).join('')}</div></details>`,btn('Apply','goal-filter-apply','','primary'));}
function applyGoalFilter(){const f={operator:$('#goal-filter-operator').value,values:$$('input[name="goal-filter-value"]:checked').map(input=>input.value)};if(!validGoalFilters([f]).length)return toast('Select at least one performance goal.');if(!commitFilterValue('goalFilters',f))return;state.page=0;state.selection.clear();persist();$('#popover').hidden=true;render();}

function mergeConfigurationBudget(row,source){if(!Object.hasOwn(row,'Ad set budget')&&!Object.hasOwn(row,'Ad set budget type')&&source.budgetSource&&Object.hasOwn(source,'Ad set budget')){row['Ad set budget']=source['Ad set budget'];row['Ad set budget type']=source['Ad set budget type'];row.budgetSource=source.budgetSource;}}

function scheduleOrderValid(start,end,startTime,endTime,startOffset,endOffset){if(!start||!end)return true;if(startTime&&endTime&&startOffset&&endOffset){const a=Date.parse(start+'T'+startTime+startOffset),b=Date.parse(end+'T'+endTime+endOffset);return Number.isFinite(a)&&Number.isFinite(b)&&b>=a;}if(end<start)return false;const normalize=value=>/^\d{2}:\d{2}$/.test(value)?value+':00':value;return end!==start||!startTime||!endTime||normalize(endTime)>=normalize(startTime);}
function mergeScheduleSettings(row,source){
 const incoming=source.exportedSettings||{};row.exportedSettings||={};
 for(const key of ['start','end']){
  if(Object.hasOwn(row,key)||Object.hasOwn(row,key+'Time'))continue;
  if(row.exportedSettings[key]!==incoming[key])continue;
  for(const suffix of ['Time','TimeOffset'])if(!Object.hasOwn(row.exportedSettings,key+suffix)&&Object.hasOwn(incoming,key+suffix))row.exportedSettings[key+suffix]=incoming[key+suffix];
 }
}

function validSchedulePatch(row,patch){if(!row)return true;const value={...row.exportedSettings,...row};for(const [key,field] of [['start','edit-start'],['end','edit-end'],['startTime','edit-start-time'],['endTime','edit-end-time']])if(Object.hasOwn(patch,field))value[key]=patch[field];return scheduleOrderValid(value.start,value.end,value.startTime,value.endTime,value.startTimeOffset,value.endTimeOffset);}

function editorFieldValue(el){return el.type==='checkbox'?el.checked:el.value;}
function placementFieldChoices(){return {platforms:{label:'Platforms',choices:[['facebook','Facebook'],['instagram','Instagram'],['messenger','Messenger'],['audience_network','Audience Network']]},devicePlatforms:{label:'Devices',choices:[['mobile','Mobile'],['desktop','Desktop']]},facebookPositions:{label:'Facebook placements',choices:[['feed','Facebook Feed'],['story','Facebook Stories'],['facebook_reels','Facebook Reels'],['marketplace','Facebook Marketplace'],['notification','Facebook notifications'],['profile_feed','Facebook profile feed'],['right_hand_column','Facebook right column'],['search','Facebook search results']]},instagramPositions:{label:'Instagram placements',choices:[['stream','Instagram Feed'],['story','Instagram Stories'],['reels','Instagram Reels'],['ig_search','Instagram search results'],['profile_feed','Instagram profile feed'],['explore_home','Instagram Explore home']]}};}
function placementTokens(value){return String(value||'').split(',').map(x=>x.trim()).filter(Boolean);}
function placementEditorFields(row){return `<details class="placement-editor"><summary>Platforms, devices and placements</summary>${Object.entries(placementFieldChoices()).map(([field,{label,choices}])=>{const tokens=placementTokens(row[field]),unknown=tokens.filter(t=>!choices.some(([key])=>key===t));return `<fieldset><legend>${esc(label)}</legend>${!Object.hasOwn(row,field)?'<p class="small muted">Selection unavailable in export.</p>':''}${choices.map(([key,title])=>`<label><input type="checkbox" id="edit-placement-${field}-${key}" ${tokens.includes(key)?'checked':''}>${esc(title)}</label>`).join('')}${unknown.length?`<p class="small muted">${unknown.length} additional exported placements will be retained.</p>`:''}</fieldset>`}).join('')}</details>`;}
function applyPlacementPatch(row,patch){let changed=false;for(const [field,{choices}] of Object.entries(placementFieldChoices())){const tokens=new Set(placementTokens(row[field]??row.exportedSettings?.[field]));let touched=false;for(const [key] of choices){const id='edit-placement-'+field+'-'+key;if(Object.hasOwn(patch,id)){if(patch[id]===true)tokens.add(key);else if(patch[id]===false)tokens.delete(key);else continue;touched=true;}}if(touched){const value=[...tokens].join(', ');if(value!==(row[field]??row.exportedSettings?.[field]??'')){row[field]=value;changed=true;}}}if(changed)row.placements='Manual placements';return changed;}
function mergePlacementSettings(row,source){const incoming=source.exportedSettings||{};row.exportedSettings||={};for(const key of ['platforms','devicePlatforms','facebookPositions','instagramPositions','audienceNetworkPositions','messengerPositions'])if(!Object.hasOwn(row,key)&&!Object.hasOwn(row.exportedSettings,key)&&Object.hasOwn(incoming,key))row.exportedSettings[key]=incoming[key];}

function reviewSettingsDetails(row,level){
 const settings={...row.exportedSettings,...row},pairs=[];
 for(const [key,label] of [['start','Start'],['end','End']])if(Object.hasOwn(settings,key))pairs.push([label,settings[key]?settings[key]+(settings[key+'Time']?' '+settings[key+'Time']:'')+(settings[key+'TimeOffset']?' UTC'+settings[key+'TimeOffset']:''):key==='end'?'No end date':'Not set']);
 const performanceGoal=effectivePerformanceGoal(row,level);if(performanceGoal)pairs.push(['Performance goal',performanceGoal]);
 if(settings.placements)pairs.push(['Placements',settings.placements]);
 for(const [field,{label,choices}] of Object.entries(placementFieldChoices()))if(Object.hasOwn(settings,field)){
  const tokens=placementTokens(settings[field]),known=tokens.map(token=>choices.find(([key])=>key===token)?.[1]).filter(Boolean),extra=tokens.length-known.length;
  const platform=field==='facebookPositions'?'facebook':field==='instagramPositions'?'instagram':'';const inactive=platform&&Object.hasOwn(settings,'platforms')&&!placementTokens(settings.platforms).includes(platform);
  pairs.push([label+(inactive?' (inactive)':''),[...known,...(extra?[extra+' additional exported selections']:[])].join(', ')||'None selected']);
 }
 return pairs.map(([label,value])=>`<dt>${esc(label)}</dt><dd>${esc(value)}</dd>`).join('');
}

function globalSearchCatalog(){
 return [
  {id:'account',name:company.companyName,detail:company.accountId,group:'Ad accounts',icon:'megaphone',command:'account'},
  ...[['Ads Manager','table','Campaigns'],['Billing & payments','card'],['Audiences','people'],['Business settings','settings'],['Events Manager','network'],['Commerce Manager','box'],['Ads Reporting','report'],['Advertising settings','megaphone'],['Account overview','gauge']].map(([name,ic,target])=>({id:'tool:'+name,name,group:'Tools',icon:ic,command:'nav:'+(target||name)}))
 ];
}
function searchRecentIds(){
 const catalog=globalSearchCatalog();let ids=Array.isArray(company.searchRecentTools)?company.searchRecentTools.filter(name=>typeof name==='string').map(name=>'tool:'+name):[];
 try{const saved=JSON.parse(localStorage.getItem(company.storageKey+'-global-search'));if(Array.isArray(saved))ids=saved;}catch{}
 return [...new Set(ids.filter(id=>typeof id==='string'&&catalog.some(r=>r.id===id)))].slice(0,6);
}
function globalSearchMatches(query){
 const text=String(query||'').trim().toLocaleLowerCase(company.locale),catalog=globalSearchCatalog();
 if(text)return catalog.filter(r=>(r.name+' '+(r.detail||'')).toLocaleLowerCase(company.locale).includes(text));
 const recent=searchRecentIds();return recent.length?recent.map(id=>catalog.find(r=>r.id===id)):catalog.filter(r=>r.group==='Tools').slice(0,6);
}
let globalSearchActive=0;
function renderGlobalSearchResults(){
 const input=$('#global-search-input'),query=input.value,rows=globalSearchMatches(query);globalSearchActive=Math.min(Math.max(globalSearchActive,0),Math.max(0,rows.length-1));
 const groups=[...new Set(rows.map(r=>query.trim()?r.group:(searchRecentIds().length?'Recently viewed':'Tools')))];
 $('#global-search-results').innerHTML=groups.map(group=>`<h3>${esc(group)}</h3>${rows.map((r,index)=>({r,index})).filter(({r})=>!query.trim()||r.group===group).map(({r,index})=>`<button id="global-search-result-${index}" role="option" aria-selected="${index===globalSearchActive}" class="global-search-result" data-action="global-search-result:${encodeURIComponent(r.id)}">${icon(r.icon)}<span>${esc(r.name)}${r.detail?`<small>${esc(r.detail)}</small>`:''}</span></button>`).join('')}`).join('')||'<p class="global-search-empty">No results found in this snapshot.</p>';
 input.setAttribute('aria-activedescendant',rows.length?'global-search-result-'+globalSearchActive:'');
 $('#global-search-status').textContent=`Found ${rows.length} results`;
}
function showGlobalSearch(){
 globalSearchActive=0;
 modal('Search',`<div class="global-search-shell"><label class="global-search-field">${icon('search')}<input id="global-search-input" role="combobox" aria-label="Search accounts and tools" aria-autocomplete="list" aria-expanded="true" aria-controls="global-search-results" placeholder="Find ad accounts, Pages, people, tools and help articles" autocomplete="off"></label><div id="global-search-results" role="listbox" aria-label="Search results"></div><div class="global-search-bottom"><span>⌘+K</span><span id="global-search-status" class="sr-only" role="status" aria-live="polite"></span></div></div>`,'',600);
 const input=$('#global-search-input');input.value='';input.addEventListener('input',()=>{globalSearchActive=0;renderGlobalSearchResults();});input.addEventListener('keydown',handleGlobalSearchKey);renderGlobalSearchResults();input.focus();
}
function handleGlobalSearchKey(event){
 const rows=globalSearchMatches($('#global-search-input').value);
 if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();if(rows.length)globalSearchActive=(globalSearchActive+(event.key==='ArrowDown'?1:-1)+rows.length)%rows.length;renderGlobalSearchResults();$('#global-search-result-'+globalSearchActive)?.scrollIntoView?.({block:'nearest'});}
 else if(event.key==='Enter'&&rows.length){event.preventDefault();openGlobalSearchResult(rows[globalSearchActive].id);}
}
function openGlobalSearchResult(id){
 const row=globalSearchCatalog().find(r=>r.id===id);if(!row)return;
 try{localStorage.setItem(company.storageKey+'-global-search',JSON.stringify([id,...searchRecentIds().filter(r=>r!==id)].slice(0,6)));}catch{}
 $('#modal').close();action(row.command,$('#account'));
}

function showEditOptions(anchor){if(!selectedRows().length)return;menu(anchor,heading('General')+item('Turn on','bulk-on')+(company.campaignsAlwaysOn===true&&state.level==='campaigns'?'':item('Turn off','bulk-off'))+item('Name','edit-names')+item('Find and replace','find-replace')+(state.level==='campaigns'?heading('Advantage+ campaign budget')+item('Campaign budget','campaign-budget'):'')+heading('Campaign details')+item('Edit selected settings','edit','edit'),275);}
let nameEditContext=null;
function nameReplacement(name,find,replacement){
 if(!find)return name;
 const escaped=find.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 return name.replace(new RegExp(escaped,'gi'),()=>replacement);
}
function nameEditPlan(){if(!nameEditContext)return [];const find=$('#rename-find').value,replacement=$('#rename-with').value;return nameEditContext.ids.map(id=>data[nameEditContext.level].find(r=>r.id===id&&!r.deleted)).filter(Boolean).map(row=>({row,name:nameEditContext.replace?nameReplacement(row.name,find,replacement):replacement}));}
function updateNameEditPreview(){
 const plan=nameEditPlan(),changed=plan.filter(p=>p.name!==p.row.name),valid=changed.length>0&&changed.every(p=>p.name.trim().length>0);
 $('#rename-preview').innerHTML=plan.map(({row,name})=>`<tr><td title="${esc(row.name)}">${esc(row.name)}</td><td title="${esc(name)}">${name===row.name?'–':esc(name)}</td></tr>`).join('');
 $('#rename-summary').textContent=nameEditContext.replace?`"${$('#rename-find').value}" appeared in ${changed.length} of ${plan.length} objects`:`${changed.length} of ${plan.length} names will change`;
 $('#rename-with').disabled=nameEditContext.replace&&!$('#rename-find').value;
 $('#rename-save').disabled=!valid;
}
function showNameEdit(replace=true){
 const rows=selectedRows();if(!rows.length)return;nameEditContext={level:state.level,ids:rows.map(r=>r.id),replace};
 modal((replace?'Replace text in ':'Edit ')+rows.length+' '+singular[state.level].toLowerCase()+' name'+(rows.length===1?'':'s'),`<div class="name-edit-shell"><div class="name-edit-fields">${replace?'<label>Replace<input id="rename-find" placeholder="This word or phrase"></label>':'<input id="rename-find" type="hidden">'}<label>${replace?'with':'Name'}<input id="rename-with" placeholder="${replace?'This word or phrase':'Enter a name'}"></label></div><div class="name-edit-table"><table><thead><tr><th>Current text</th><th>New text</th></tr></thead><tbody id="rename-preview"></tbody></table></div><p id="rename-summary" role="status"></p></div>`,btn('Save to draft','save-name-edit','','primary','id="rename-save" disabled'),667);
 $('#rename-find').value='';$('#rename-with').value=replace?'':rows.length===1?rows[0].name:'';
 for(const selector of ['#rename-find','#rename-with'])$(selector).addEventListener('input',updateNameEditPreview);updateNameEditPreview();$(replace?'#rename-find':'#rename-with').focus();
}
function renameLocalRecord(row,level,name){
 const field=singular[level]+' name';row.name=name;row[field]=name;
 function updateChildren(parent,current){for(const child of duplicateChildren(parent,current)){child[field]=name;if(current!=='ads')updateChildren(child,current==='campaigns'?'adsets':'ads');}}
 if(level!=='ads')updateChildren(row,level);
}
function saveNameEdit(){
 const plan=nameEditPlan().filter(p=>p.name!==p.row.name);if(!plan.length)return;
 if(plan.some(p=>!p.name.trim()))return toast('Names cannot be empty.');
 const level=nameEditContext.level,time=new Date().toISOString();
 for(const {row,name} of plan){const old=row.name;renameLocalRecord(row,level,name);const entry={id:row.id,level,name,description:`Renamed from "${old}" to "${name}" locally`,time};pending.push(entry);history.unshift({...entry});}
 persist();$('#modal').close();nameEditContext=null;render();toast(`Saved ${plan.length} name changes as local drafts.`);
}

let campaignBudgetContext=null;
function dailyCampaignBudget(row){const value=filterNumber(row['Ad set budget']);return row['Ad set budget type']==='Daily'&&value!==null&&value>=0?value:null;}
function calculateBudgetAmount(before,mode,value,unit){
 if(!Number.isFinite(before)||before<0||!Number.isFinite(value)||value<0||!['set','increase','decrease'].includes(mode)||!['currency','percent'].includes(unit))return null;
 const digits=new Intl.NumberFormat(company.locale,{style:'currency',currency:company.currency}).resolvedOptions().maximumFractionDigits;
 const delta=unit==='percent'?before*value/100:value;
 const result=mode==='set'?value:mode==='increase'?before+delta:before-delta;
 if(!Number.isFinite(result)||result<=0)return null;
 const rounded=Number(result.toFixed(digits));return rounded>0&&Number.isSafeInteger(Math.round(rounded*10**digits))?rounded:null;
}
function budgetPreviewPlan(){return (campaignBudgetContext?.rows||[]).map(item=>({...item,after:Object.hasOwn(campaignBudgetContext.draft,item.id)?campaignBudgetContext.draft[item.id]:item.before}));}
function updateBudgetPreview(){
 const plan=budgetPreviewPlan(),eligible=plan.filter(r=>r.before!==null),valid=eligible.every(r=>Number.isFinite(r.after)&&r.after>0),changed=eligible.filter(r=>r.after!==r.before);
 for(const row of plan){const input=$('#budget-row-'+row.id);if(input)input.value=row.after===null?'':row.after;}
 $('#budget-total').textContent=`Total daily budget: ${valid?money(eligible.reduce((n,r)=>n+r.after,0)):'Invalid amount'} (was ${money(eligible.reduce((n,r)=>n+r.before,0))})`;
 $('#budget-save').disabled=!valid||!changed.length;
}
function applyBudgetAdjustment(event){
 if(!campaignBudgetContext)return;if(event?.target?.id==='budget-adjust-mode'){$('#budget-adjust-unit').value=$('#budget-adjust-mode').value==='set'?'currency':'percent';$('#budget-adjust-value').value='';}const mode=$('#budget-adjust-mode').value,value=filterNumber($('#budget-adjust-value').value),unit=mode==='set'?'currency':$('#budget-adjust-unit').value;
 $('#budget-adjust-unit').disabled=mode==='set';
 for(const row of campaignBudgetContext.rows)if(row.before!==null)campaignBudgetContext.draft[row.id]=value===null?row.before:calculateBudgetAmount(row.before,mode,value,unit);
 updateBudgetPreview();
}
function showCampaignBudget(){
 const rows=selectedRows();if(state.level!=='campaigns'||!rows.length)return;
 campaignBudgetContext={rows:rows.map(row=>({id:row.id,name:row.name,before:dailyCampaignBudget(row)})),draft:{}};
 const eligible=campaignBudgetContext.rows.filter(r=>r.before!==null),same=eligible.length&&eligible.every(r=>r.before===eligible[0].before);
 modal(`Campaign budget for ${rows.length} campaign${rows.length===1?'':'s'}`,`<div class="campaign-budget-shell"><aside class="budget-objects"><b>Campaigns　${rows.length}</b>${rows.map(r=>`<p>${icon('folder')}${esc(r.name)}</p>`).join('')}</aside><aside class="budget-settings"><h3>General</h3>${btn('Name','budget-edit-name','','flat')}<h3>Advantage+ campaign budget</h3><strong>Campaign budget</strong></aside><section class="budget-main"><h3>Campaign budget</h3><div class="budget-table-scroll"><table class="budget-table"><thead><tr><th>Campaign name</th><th>Amount spent<br><small>${esc(company.reportStart)} – ${esc(company.reportEnd)}</small></th><th>Campaign budget</th></tr></thead><tbody><tr class="budget-bulk-row"><td colspan="2">Edit all selected campaigns</td><td><div class="budget-control"><select id="budget-adjust-mode" aria-label="Budget selector"><option value="set">Set daily budget to</option><option value="increase">Increase daily budget by</option><option value="decrease">Decrease daily budget by</option></select><input id="budget-adjust-value" aria-label="Budget adjustment" type="number" min="0" step="any"><select id="budget-adjust-unit" aria-label="Unit"><option value="currency">${esc(company.currency)}</option><option value="percent">%</option></select></div></td></tr>${rows.map(row=>{const before=dailyCampaignBudget(row);return `<tr><td>${esc(row.name)}</td><td>${filterNumber(row['Amount spent (INR)'])===null?'—':money(row['Amount spent (INR)'])}</td><td>${before===null?'<span class="muted">No editable daily campaign budget</span>':`<div class="budget-control"><span>Daily budget</span><input id="budget-row-${row.id}" data-budget-row="${row.id}" aria-label="Daily budget for ${esc(row.name)}" type="number" min="0" step="any"><span>${esc(company.currency)}</span></div>`}</td></tr>`}).join('')}</tbody></table></div><p id="budget-total"></p>${eligible.length!==rows.length?'<p class="small muted">Only existing daily campaign budgets can be adjusted here. Other budget owners and periods remain unchanged.</p>':''}</section></div>`,btn('Save to draft','save-campaign-budget','','primary','id="budget-save" disabled'),1900);
 $('#budget-adjust-mode').value='set';$('#budget-adjust-unit').value='currency';$('#budget-adjust-value').value=same?eligible[0].before:'';
 for(const selector of ['#budget-adjust-mode','#budget-adjust-unit','#budget-adjust-value'])$(selector).addEventListener('input',applyBudgetAdjustment);
 for(const row of eligible)$('#budget-row-'+row.id).addEventListener('input',event=>{const value=filterNumber(event.target.value);campaignBudgetContext.draft[row.id]=value!==null?calculateBudgetAmount(row.before,'set',value,'currency'):null;updateBudgetPreview();});
 applyBudgetAdjustment();
}
function saveCampaignBudget(){
 if(!campaignBudgetContext)return;const plan=budgetPreviewPlan().filter(r=>r.before!==null);
 if(plan.some(r=>!Number.isFinite(r.after)||r.after<=0))return toast('Enter a positive budget for every editable campaign.');
 const changed=plan.filter(r=>r.after!==r.before),time=new Date().toISOString();if(!changed.length)return;
 if(changed.some(item=>{const row=data.campaigns.find(r=>r.id===item.id&&!r.deleted);return !row||dailyCampaignBudget(row)!==item.before;}))return toast('A campaign budget changed. Reopen the budget editor.');
 for(const item of changed){const row=data.campaigns.find(r=>r.id===item.id);row['Ad set budget']=String(item.after);const entry={id:row.id,name:row.name,level:'campaigns',time,description:`Daily budget changed from ${money(item.before)} to ${money(item.after)} locally`};pending.push(entry);history.unshift({...entry});}
 persist();$('#modal').close();campaignBudgetContext=null;render();toast(`Saved ${changed.length} campaign budget changes as local drafts.`);
}

function validHierarchyScope(value,target=state.level){
 if(!value||!['campaigns','adsets'].includes(value.level)||!Array.isArray(value.ids)||['campaigns','adsets','ads'].indexOf(value.level)>=['campaigns','adsets','ads'].indexOf(target))return null;
 const ids=[...new Set(value.ids.filter(id=>typeof id==='string'&&id.length>0))];return ids.length?{level:value.level,ids}:null;
}
function hierarchySelections(level){const ids=level===state.level?[...state.selection]:(state.levelSelections?.[level]||[]);return ids.filter(id=>data[level].some(r=>r.id===id&&!r.deleted));}
function scopeForLevel(level){
 if(level==='campaigns')return null;
 const adsets=hierarchySelections('adsets'),campaigns=hierarchySelections('campaigns');
 if(level==='ads'&&adsets.length)return {level:'adsets',ids:adsets};
 return campaigns.length?{level:'campaigns',ids:campaigns}:null;
}
function hierarchyTabLabel(level){const scope=scopeForLevel(level);return labels[level]+(scope?` for ${scope.ids.length} ${scope.ids.length===1?singular[scope.level]:labels[scope.level]}`:'');}
function matchesHierarchyScope(row,level,scope){if(!scope)return true;const ids=new Set(scope.ids);return relatedMetricRows(row,level,scope.level).some(parent=>ids.has(parent.id)&&!parent.deleted);}
function navigateDashboardLevel(level){
 if(!Object.hasOwn(labels,level))return;
 state.levelSelections??={campaigns:[],adsets:[],ads:[]};
 const selected=hierarchySelections(state.level),old=state.levelSelections[state.level]||[];
 if(selected.length!==old.length||selected.some(id=>!old.includes(id))){if(state.level==='campaigns'){state.levelSelections.adsets=[];state.levelSelections.ads=[];}else if(state.level==='adsets')state.levelSelections.ads=[];}
 state.levelSelections[state.level]=selected;
 const scope=scopeForLevel(level);state.level=level;state.parent=null;state.hierarchyScope=scope;state.selection=new Set(state.levelSelections[level]||[]);state.page=0;
 state.selection=new Set([...state.selection].filter(id=>{const row=data[level].find(r=>r.id===id&&!r.deleted);return row&&matchesHierarchyScope(row,level,scope);}));render();
}
function clearHierarchyScope(){state.parent=null;state.hierarchyScope=null;state.levelSelections={campaigns:[],adsets:[],ads:[]};state.selection.clear();render();}
